/// The code the test server accepts. Invented for tests; no real code is ever in the repo.
pub const VALID_CODE: &str = "TESTC-0DE00-00000-00001";
pub const DAY: time::Duration = time::Duration::days(1);

/// A certificate authority made in memory.
pub struct Ca {
    params: CertificateParams,
    key: KeyPair,
    pub der: CertificateDer<'static>,
}

impl Ca {
    pub fn root(name: &str) -> Self {
        let params = ca_params(name, 1);
        let key = KeyPair::generate().unwrap();
        let der = params.self_signed(&key).unwrap().der().clone();
        Self { params, key, der }
    }

    pub fn intermediate(&self, name: &str) -> Self {
        let params = ca_params(name, 0);
        let key = KeyPair::generate().unwrap();
        let der = params.signed_by(&key, &self.issuer()).unwrap().der().clone();
        Self { params, key, der }
    }

    fn issuer(&self) -> Issuer<'_, &KeyPair> {
        Issuer::from_params(&self.params, &self.key)
    }

    /// A host certificate for `public_key` as our CA writes them (ADR 0010), expiring `valid_for`
    /// from now (negative for an expired one).
    pub fn host_certificate(
        &self,
        public_key: &impl PublicKeyData,
        host_id: Uuid,
        valid_for: time::Duration,
    ) -> Vec<u8> {
        let now = OffsetDateTime::now_utc();
        let mut params = CertificateParams::default();
        params.distinguished_name = DistinguishedName::new();
        params.subject_alt_names = vec![SanType::URI(format!("urn:idleo:host:{host_id}").try_into().unwrap())];
        params.is_ca = IsCa::ExplicitNoCa;
        params.key_usages = vec![KeyUsagePurpose::DigitalSignature];
        params.extended_key_usages = vec![ExtendedKeyUsagePurpose::ClientAuth];
        params.not_after = now + valid_for;
        params.not_before = (now - time::Duration::hours(1)).min(params.not_after - 30 * DAY);
        params.signed_by(public_key, &self.issuer()).unwrap().der().to_vec()
    }

    /// A server certificate for `localhost`.
    pub fn server_certificate(&self) -> (CertificateDer<'static>, PrivateKeyDer<'static>) {
        let key = KeyPair::generate().unwrap();
        let mut params = CertificateParams::new(vec!["localhost".to_owned()]).unwrap();
        params.extended_key_usages = vec![ExtendedKeyUsagePurpose::ServerAuth];
        let der = params.signed_by(&key, &self.issuer()).unwrap().der().clone();
        (der, PrivatePkcs8KeyDer::from(key.serialize_der()).into())
    }
}

fn ca_params(name: &str, path_length: u8) -> CertificateParams {
    let mut params = CertificateParams::default();
    params.distinguished_name.push(DnType::CommonName, name);
    params.is_ca = IsCa::Ca(BasicConstraints::Constrained(path_length));
    params.key_usages = vec![KeyUsagePurpose::KeyCertSign, KeyUsagePurpose::CrlSign];
    params
}

/// Our test PKI: root, intermediate, and the control plane's server certificate.
pub struct Pki {
    pub root: Ca,
    pub intermediate: Ca,
}

impl Pki {
    pub fn new() -> Self {
        let root = Ca::root("IdleO Test Root");
        let intermediate = root.intermediate("IdleO Test Intermediate");
        Self { root, intermediate }
    }

    /// The agent's trust store: our root only.
    pub fn agent_roots(&self) -> Arc<RootCertStore> {
        idleo_agent::pki::roots_from(vec![self.root.der.clone()]).unwrap()
    }

    /// A chain the CA would return: host certificate, then intermediate.
    pub fn host_chain(
        &self,
        public_key: &impl PublicKeyData,
        host_id: Uuid,
        valid_for: time::Duration,
    ) -> Vec<Vec<u8>> {
        vec![self.intermediate.host_certificate(public_key, host_id, valid_for), self.intermediate.der.to_vec()]
    }
}

/// How the server answers one `OpenStream`.
#[derive(Debug, Clone)]
pub enum Stream {
    /// Welcome with this heartbeat interval; then, optionally, end the stream after a while.
    Welcome { interval: Duration, end_after: Option<(Duration, Code)> },
    /// Welcome with a zero heartbeat interval.
    ZeroInterval,
    /// Fail with this status right after Hello.
    Fail(Code),
}

impl Stream {
    pub fn welcome(interval: Duration) -> Self {
        Self::Welcome { interval, end_after: None }
    }
}

#[derive(Debug, Clone, Copy)]
pub enum Enrol {
    Sign,
    FromAnotherCa,
    ForAnotherKey,
}

#[derive(Debug, Clone, Copy)]
pub enum Renew {
    Sign,
    FailedPrecondition,
}

/// One `OpenStream` call as the server saw it.
#[derive(Debug)]
pub struct Connection {
    pub opened: Instant,
    pub client_certificate: Option<Vec<u8>>,
    pub messages: Vec<(Instant, OpenStreamRequest)>,
    pub welcomed: Option<Instant>,
    pub ended_by_agent: bool,
}

pub struct Behaviour {
    pub host_id: Uuid,
    pub enrol: Enrol,
    pub enrol_valid_for: time::Duration,
    pub renew: Renew,
    pub streams: VecDeque<Stream>,
    pub default_stream: Stream,
}

#[derive(Default)]
pub struct Recorded {
    pub connections: Vec<Connection>,
    pub csrs: Vec<Vec<u8>>,
    pub renewals: usize,
}

pub struct Shared {
    pub behaviour: Mutex<Behaviour>,
    recorded: Mutex<Recorded>,
    changed: Notify,
    pki: Pki,
}

impl Shared {
    pub fn recorded(&self) -> MutexGuard<'_, Recorded> {
        self.recorded.lock().unwrap()
    }

    fn record(&self, change: impl FnOnce(&mut Recorded)) {
        change(&mut self.recorded());
        self.changed.notify_waiters();
    }
}

/// A running test control plane.
pub struct TestServer {
    pub shared: Arc<Shared>,
    pub target: Target,
    tasks: Vec<JoinHandle<()>>,
}

impl Drop for TestServer {
    fn drop(&mut self) {
        for task in &self.tasks {
            task.abort();
        }
    }
}

/// Which TLS versions and server certificate the test server uses.
pub struct ServerTls {
    pub versions: &'static [&'static SupportedProtocolVersion],
    pub certificate_from_another_ca: bool,
}

pub static TLS13_ONLY: &[&SupportedProtocolVersion] = &[&rustls::version::TLS13];
pub static TLS12_ONLY: &[&SupportedProtocolVersion] = &[&rustls::version::TLS12];

impl Default for ServerTls {
    fn default() -> Self {
        Self { versions: TLS13_ONLY, certificate_from_another_ca: false }
    }
}

impl TestServer {
    /// Over TCP on 127.0.0.1, for tests on the real clock.
    pub async fn tcp() -> Self {
        Self::tcp_with(ServerTls::default()).await
    }

    pub async fn tcp_with(tls: ServerTls) -> Self {
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let port = listener.local_addr().unwrap().port();
        let (sockets, incoming) = mpsc::channel(16);
        let accept = tokio::spawn(async move {
            while let Ok((socket, _)) = listener.accept().await {
                if sockets.send(socket).await.is_err() {
                    break;
                }
            }
        });
        let target = Target {
            dialer: Dialer::tcp("127.0.0.1".to_owned(), port),
            server_name: ServerName::try_from("localhost").unwrap(),
            authority: format!("localhost:{port}"),
        };
        Self::start(target, incoming, &tls, accept)
    }

    /// Over an in-memory pipe, still with TLS 1.3 and client certificates, for tests on tokio's
    /// paused clock.
    pub fn in_memory() -> Self {
        let (pipes, incoming) = mpsc::channel(16);
        let dialer = Dialer::custom(move || {
            let pipes = pipes.clone();
            async move {
                let (agent, server) = tokio::io::duplex(1 << 16);
                pipes.send(server).await.map_err(|_| io::Error::from(io::ErrorKind::ConnectionRefused))?;
                Ok(Box::new(agent) as Box<dyn Io>)
            }
        });
        let target = Target {
            dialer,
            server_name: ServerName::try_from("localhost").unwrap(),
            authority: "localhost:443".to_owned(),
        };
        Self::start(target, incoming, &ServerTls::default(), tokio::spawn(async {}))
    }

    fn start<S>(target: Target, incoming: mpsc::Receiver<S>, tls: &ServerTls, accept: JoinHandle<()>) -> Self
    where
        S: AsyncRead + AsyncWrite + Connected + Unpin + Send + 'static,
    {
        let pki = Pki::new();
        let (server_der, server_key) = if tls.certificate_from_another_ca {
            Ca::root("Another CA").server_certificate()
        } else {
            pki.intermediate.server_certificate()
        };
        let mut client_roots = RootCertStore::empty();
        client_roots.add(pki.root.der.clone()).unwrap();
        let verifier =
            WebPkiClientVerifier::builder_with_provider(Arc::new(client_roots), idleo_agent::tls::provider())
                .allow_unauthenticated()
                .build()
                .unwrap();
        let mut config = ServerConfig::builder_with_provider(idleo_agent::tls::provider())
            .with_protocol_versions(tls.versions)
            .unwrap()
            .with_client_cert_verifier(verifier)
            .with_single_cert(vec![server_der, pki.intermediate.der.clone()], server_key)
            .unwrap();
        config.alpn_protocols = vec![b"h2".to_vec()];
        let acceptor = TlsAcceptor::from(Arc::new(config));

        let shared = Arc::new(Shared {
            behaviour: Mutex::new(Behaviour {
                host_id: Uuid::now_v7(),
                enrol: Enrol::Sign,
                enrol_valid_for: 30 * DAY,
                renew: Renew::Sign,
                streams: VecDeque::new(),
                default_stream: Stream::welcome(Duration::from_secs(5)),
            }),
            recorded: Mutex::new(Recorded::default()),
            changed: Notify::new(),
            pki,
        });
        let service = Service(Arc::clone(&shared));
        let serve = tokio::spawn(async move {
            let (streams, tls_incoming) = mpsc::channel::<io::Result<tokio_rustls::server::TlsStream<S>>>(16);
            let mut incoming = incoming;
            tokio::spawn(async move {
                while let Some(stream) = incoming.recv().await {
                    let acceptor = acceptor.clone();
                    let streams = streams.clone();
                    tokio::spawn(async move {
                        // A failed handshake is the agent refusing us (or us refusing it): drop it.
                        if let Ok(tls) = acceptor.accept(stream).await {
                            let _ = streams.send(Ok(tls)).await;
                        }
                    });
                }
            });
            let _ = tonic::transport::Server::builder()
                .add_service(EnrollmentServiceServer::new(service.clone()))
                .add_service(AgentGatewayServiceServer::new(service))
                .serve_with_incoming(ReceiverStream::new(tls_incoming))
                .await;
        });
        Self { shared, target, tasks: vec![accept, serve] }
    }

    pub fn pki(&self) -> &Pki {
        &self.shared.pki
    }

    pub fn host_id(&self) -> Uuid {
        self.shared.behaviour.lock().unwrap().host_id
    }

    pub fn behave(&self, change: impl FnOnce(&mut Behaviour)) {
        change(&mut self.shared.behaviour.lock().unwrap());
    }

    pub fn recorded(&self) -> MutexGuard<'_, Recorded> {
        self.shared.recorded()
    }

    /// Waits until `condition` holds, or panics after `limit` (on whichever clock the test uses).
    pub async fn wait_until(&self, limit: Duration, condition: impl Fn(&Recorded) -> bool) {
        let deadline = Instant::now() + limit;
        loop {
            let changed = self.shared.changed.notified();
            tokio::pin!(changed);
            changed.as_mut().enable();
            if condition(&self.recorded()) {
                return;
            }
            assert!(
                tokio::time::timeout_at(deadline, changed).await.is_ok(),
                "the test server didn't see the expected state within {limit:?}"
            );
        }
    }

    /// Enrols an agent into `data_dir` with the valid code.
    pub async fn enrol(&self, data_dir: &Path) -> Enrolled {
        let code = EnrolmentCode::parse(VALID_CODE).unwrap();
        enrol::enrol(&self.target, &self.pki().agent_roots(), data_dir, &code, false).await.unwrap()
    }

    /// Options to run an agent against this server with one fake GPU.
    pub fn run_options(&self, data_dir: &Path, timing: Timing) -> (RunOptions, mpsc::UnboundedReceiver<Event>) {
        let (events, received) = mpsc::unbounded_channel();
        let options = RunOptions {
            target: self.target.clone(),
            roots: self.pki().agent_roots(),
            data_dir: data_dir.to_owned(),
            gpus: Arc::new(FakeGpus::new(1)),
            owner: Arc::new(Owner(false)),
            timing,
            events: Some(events),
        };
        (options, received)
    }
}

/// Runs the agent in the background until the returned sender is set to true.
pub fn spawn_agent(
    options: RunOptions,
) -> (watch::Sender<bool>, JoinHandle<Result<(), idleo_agent::connection::RunError>>) {
    let (stop, shutdown) = watch::channel(false);
    (stop, tokio::spawn(idleo_agent::connection::run(options, shutdown)))
}

/// The next event matching `wanted`, skipping others.
pub async fn next_event(events: &mut mpsc::UnboundedReceiver<Event>, wanted: impl Fn(&Event) -> bool) -> Event {
    loop {
        let event = events.recv().await.expect("the agent stopped sending events");
        if wanted(&event) {
            return event;
        }
    }
}

pub struct Owner(pub bool);

impl OwnerActivity for Owner {
    fn is_active(&self) -> bool {
        self.0
    }
}

#[derive(Clone)]
struct Service(Arc<Shared>);

fn peer_certificate<T>(request: &Request<T>) -> Option<Vec<u8>> {
    let certificates = request
        .extensions()
        .get::<TlsConnectInfo<TcpConnectInfo>>()
        .and_then(TlsConnectInfo::peer_certs)
        .or_else(|| request.extensions().get::<TlsConnectInfo<()>>().and_then(TlsConnectInfo::peer_certs))?;
    certificates.first().map(|der| der.to_vec())
}

fn public_key_of_csr(csr_der: &[u8]) -> Result<rcgen::PublicKey, Status> {
    CertificateSigningRequestParams::from_der(&csr_der.to_vec().into())
        .map(|csr| csr.public_key)
        .map_err(|_| Status::invalid_argument("bad CSR"))
}

#[tonic::async_trait]
impl EnrollmentService for Service {
    async fn enroll(&self, request: Request<EnrollRequest>) -> Result<Response<EnrollResponse>, Status> {
        let request = request.into_inner();
        self.0.record(|r| r.csrs.push(request.csr_der.clone()));
        if request.enrollment_code != VALID_CODE {
            return Err(Status::unauthenticated("Unknown, used or expired enrolment code."));
        }
        let public_key = public_key_of_csr(&request.csr_der)?;
        let (host_id, mode, valid_for) = {
            let b = self.0.behaviour.lock().unwrap();
            (b.host_id, b.enrol, b.enrol_valid_for)
        };
        let chain = match mode {
            Enrol::Sign => self.0.pki.host_chain(&public_key, host_id, valid_for),
            Enrol::FromAnotherCa => {
                let other = Ca::root("Another Root").intermediate("Another Intermediate");
                vec![other.host_certificate(&public_key, host_id, valid_for), other.der.to_vec()]
            }
            Enrol::ForAnotherKey => self.0.pki.host_chain(&KeyPair::generate().unwrap(), host_id, valid_for),
        };
        Ok(Response::new(EnrollResponse {
            certificate: Some(IssuedCertificate { certificate_chain_der: chain, not_after: None }),
        }))
    }
}

type ResponseStream = ReceiverStream<Result<OpenStreamResponse, Status>>;

fn welcome(interval: Duration) -> OpenStreamResponse {
    OpenStreamResponse {
        message_id: Uuid::now_v7().to_string(),
        body: Some(ServerBody::Welcome(Welcome {
            policy: Some(AgentPolicy {
                heartbeat_interval: Some(prost_types::Duration::try_from(interval).unwrap()),
                gpu_temp_cap_c: 85,
                max_concurrent_sessions: 1,
            }),
            minimum_agent_version: "0.1.0".to_owned(),
        })),
    }
}

#[tonic::async_trait]
impl AgentGatewayService for Service {
    type OpenStreamStream = ResponseStream;

    async fn open_stream(
        &self,
        request: Request<Streaming<OpenStreamRequest>>,
    ) -> Result<Response<Self::OpenStreamStream>, Status> {
        let client_certificate = peer_certificate(&request);
        let Some(_) = client_certificate else {
            return Err(Status::unauthenticated("A client certificate is required."));
        };
        let index = {
            let mut recorded = self.0.recorded();
            recorded.connections.push(Connection {
                opened: Instant::now(),
                client_certificate,
                messages: Vec::new(),
                welcomed: None,
                ended_by_agent: false,
            });
            recorded.connections.len() - 1
        };
        self.0.changed.notify_waiters();
        let stream = {
            let mut b = self.0.behaviour.lock().unwrap();
            b.streams.pop_front().unwrap_or_else(|| b.default_stream.clone())
        };
        let mut inbound = request.into_inner();
        let (outbound, responses) = mpsc::channel(16);
        let shared = Arc::clone(&self.0);
        tokio::spawn(async move {
            let mut first = true;
            while let Ok(Some(message)) = inbound.message().await {
                let now = Instant::now();
                shared.record(|r| r.connections[index].messages.push((now, message)));
                if first {
                    first = false;
                    match &stream {
                        Stream::Welcome { interval, end_after } => {
                            let _ = outbound.send(Ok(welcome(*interval))).await;
                            shared.record(|r| r.connections[index].welcomed = Some(Instant::now()));
                            if let Some((after, code)) = *end_after {
                                let outbound = outbound.clone();
                                tokio::spawn(async move {
                                    tokio::time::sleep(after).await;
                                    let _ = outbound.send(Err(Status::new(code, "ended by the test"))).await;
                                });
                            }
                        }
                        Stream::ZeroInterval => {
                            let _ = outbound.send(Ok(welcome(Duration::ZERO))).await;
                        }
                        Stream::Fail(code) => {
                            let _ = outbound.send(Err(Status::new(*code, "refused by the test"))).await;
                        }
                    }
                }
            }
            // The agent half-closed or cancelled the stream.
            shared.record(|r| r.connections[index].ended_by_agent = true);
        });
        Ok(Response::new(ReceiverStream::new(responses)))
    }

    async fn renew_certificate(
        &self,
        request: Request<RenewCertificateRequest>,
    ) -> Result<Response<RenewCertificateResponse>, Status> {
        let request = request.into_inner();
        self.0.record(|r| {
            r.renewals += 1;
            r.csrs.push(request.csr_der.clone());
        });
        let (host_id, mode) = {
            let b = self.0.behaviour.lock().unwrap();
            (b.host_id, b.renew)
        };
        match mode {
            Renew::FailedPrecondition => {
                Err(Status::failed_precondition("This certificate was already renewed; use the newer certificate."))
            }
            Renew::Sign => {
                let public_key = public_key_of_csr(&request.csr_der)?;
                let chain = self.0.pki.host_chain(&public_key, host_id, 30 * DAY);
                Ok(Response::new(RenewCertificateResponse {
                    certificate: Some(IssuedCertificate { certificate_chain_der: chain, not_after: None }),
                }))
            }
        }
    }
}

/// The messages of connection `index`, without timestamps.
pub fn messages(recorded: &Recorded, index: usize) -> Vec<OpenStreamRequest> {
    recorded.connections[index].messages.iter().map(|(_, m)| m.clone()).collect()
}

/// Timing for tests: production values except where a test shortens them.
pub fn timing() -> Timing {
    Timing::default()
}
